def fizzbuzz(n: int) -> list[str]:
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s: str) -> int:
    minutos = 0
    for caracter in s:
        if caracter == 'h':
            minutos += 60
        elif caracter == 'm':
            minutos += 1
    return minutos

def es_palindromo(s: str) -> bool:
    s = s.lower().replace(" ", "").replace(".", "").replace(",", "")
    return s == s[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    izq = 0
    der = len(lista) - 1

    while izq <= der:
        mid = (izq + der) // 2
        if lista[mid] == x:
            return mid
        elif lista[mid] < x:
            izq = mid + 1
        else:
            der = mid - 1

    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def contar_palabras(texto: str) -> dict:
    import re
    palabras = re.findall(r'\b\w+\b', texto.lower())
    return {palabra: palabras.count(palabra) for palabra in set(palabras)}

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n):
    if not (1 <= n <= 3999):
        raise ValueError("El número debe estar entre 1 y 3999")

    valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    simbolos = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    resultado = ""
    for i in range(len(valores)):
        while n >= valores[i]:
            resultado += simbolos[i]
            n -= valores[i]

    return resultado

def desde_romano(s: str) -> int:
    """Convierte un número romano en mayúsculas al entero correspondiente.

    Maneja la notación sustractiva (IV = 4, IX = 9, XL = 40, etc.).

    Args:
        s: Cadena de caracteres en mayúsculas representando un número romano.

    Returns:
        El entero correspondiente al número romano.

    Raises:
        ValueError: Si el número romano es inválido.
    """
    valores = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    if not s or not s.isupper():
        raise ValueError("El número romano debe estar en mayúsculas y no estar vacío.")

    if any(c not in valores for c in s):
        raise ValueError(f"Carácter inválido '{c}' en el número romano.")

    resultado = 0
    for i in range(len(s)):
        if i < len(s) - 1 and valores[s[i]] < valores[s[i + 1]]:
            resultado -= valores[s[i]]
        else:
            resultado += valores[s[i]]

    return resultado

def mayor_racha(lista):
    if not lista:
        return None

    elemento = lista[0]
    longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == elemento:
            longitud += 1
        else:
            elemento = lista[i]
            longitud = 1

    return (elemento, longitud)

def primos(n):
    if n < 2:
        return []
    primos = [2]
    for i in range(3, n + 1, 2):
        es_primo = True
        for j in range(3, int(i**0.5) + 1, 2):
            if i % j == 0:
                es_primo = False
                break
        if es_primo:
            primos.append(i)
    return primos

def mcd(a: int, b: int) -> int:
    if b == 0:
        return a
    return mcd(b, a % b)

def fusionar(intervalos: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not intervalos:
        return []

    intervalos.sort(key=lambda x: x[0])

    resultado = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        ultimo_inicio, ultimo_fin = resultado[-1]
        if inicio <= ultimo_fin:
            resultado[-1] = (ultimo_inicio, max(ultimo_fin, fin))
        else:
            resultado.append((inicio, fin))

    return resultado

def comprimir(s: str) -> str:
    if not s:
        return s

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(s[i - 1])
            result.append(str(count))
            count = 1

    result.append(s[-1])
    result.append(str(count))

    comprimido = ''.join(result)

    return comprimido if len(comprimido) < len(s) else s

def balanceado(texto: str) -> bool:
    pila = []
    pares = {')': '(', ']': '[', '}': '{'}

    for caracter in texto:
        if caracter in pares.values():
            pila.append(caracter)
        elif caracter in pares:
            if not pila or pila[-1] != pares[caracter]:
                return False
            pila.pop()

    return not pila

def transpuesta(m):
    if not m:
        return []
    return [[m[i][j] for i in range(len(m))] for j in range(len(m[0]))]

def raiz_digital(n):
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def sin_duplicados(lista):
    seen = set()
    resultado = []
    for elemento in lista:
        if elemento not in seen:
            seen.add(elemento)
            resultado.append(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    lista_distinta = set(lista)
    if len(lista_distinta) < n:
        return None
    return sorted(lista_distinta, reverse=True)[n - 1]

def formatear_bytes(n: int) -> str:
    if n < 1024:
        return f"{n} B"
    elif n < 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    elif n < 1024 * 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB"
    else:
        return f"{n / (1024 * 1024 * 1024):.1f} GB"
